struct Meta * cJSON_ParseMeta(const char * s) {
    struct Meta * x = NULL;
    if (NULL != s) {
        cJSON * j = cJSON_Parse(s);
        if (NULL != j) {
            x = cJSON_GetMetaValue(j);
            cJSON_Delete(j);
        }
    }
    return x;
}

struct Meta * cJSON_GetMetaValue(const cJSON * j) {
    struct Meta * x = NULL;
    if (NULL != j) {
        if (NULL != (x = cJSON_malloc(sizeof(struct Meta)))) {
            memset(x, 0, sizeof(struct Meta));
            if (!cJSON_HasObjectItem(j, "view")) { cJSON_DeleteMeta(x); return NULL; }
            if (cJSON_HasObjectItem(j, "view")) {
                if (!cJSON_IsObject(cJSON_GetObjectItemCaseSensitive(j, "view"))) { cJSON_DeleteMeta(x); return NULL; }
                x->view = cJSON_GetViewValue(cJSON_GetObjectItemCaseSensitive(j, "view"));
                if (NULL == x->view) { cJSON_DeleteMeta(x); return NULL; }
            }
        }
    }
    return x;
}

cJSON * cJSON_CreateMeta(const struct Meta * x) {
    cJSON * j = NULL;
    if (NULL != x) {
        if (NULL != (j = cJSON_CreateObject())) {
            cJSON_AddItemToObject(j, "view", cJSON_CreateView(x->view));
        }
    }
    return j;
}

